@startuml
class School {
  +name : string
}

class Person {
  +firstName : string
  +lastName : string
}

class Teacher extends Person {
  +emailAddress : string
}

class Student extends Person {
}

class ClassGroup {
  +name : string
}

class Classroom {
  +name : string
  +capacity : int
}

class Gym {
  +name : string
  +size : float
}

class Room {
}

class TeachingAssignment {
  +hours : int
}

School "1" -- "*" Teacher : employs
School "1" -- "1" Teacher : principal
Teacher "0..3" -- "*" School : teaches
Teacher "1" -- "*" TeachingAssignment
School "1" -- "*" TeachingAssignment
TeachingAssignment "1" -- "1" School
TeachingAssignment "1" -- "1" Teacher

School "1" *-- "*" Room : consists of
Room <|-- Classroom
Room <|-- Gym

Student "1" -- "1" ClassGroup : is in
ClassGroup "1" -- "1" Classroom : is assigned to
ClassGroup "1" -- "10..31" Student : contains
@enduml

